"""Exceptions raised by the stockroom parsers."""


class ParseError(ValueError):
    """A mistake in one of the plain-text files.

    ``line`` is the 1-based line number (blank and comment lines count);
    ``reason`` is the explanation without the line number. ``str(error)``
    reads ``line N: reason``.
    """

    def __init__(self, line, reason):
        self.line = line
        self.reason = reason
        super().__init__("line %d: %s" % (line, reason))

    def __reduce__(self):
        return (self.__class__, (self.line, self.reason))
