"""Text handling shared by the three file parsers.

The rules are deliberately narrower than ``str.splitlines`` / ``str.split``:
a line ends at LF (with one optional CR before it) and nowhere else, and the
only whitespace is the space and the tab.
"""

import datetime
import re

BLANK = " \t"
FIELD_SPLIT = re.compile(r"[ \t]+")
SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+")
UINT_RE = re.compile(r"[0-9]+")


def as_text(text):
    """Return ``text`` as ``str`` (bytes are decoded as strict UTF-8)."""
    if isinstance(text, (bytes, bytearray)):
        return bytes(text).decode("utf-8")
    return text


def split_lines(text):
    """Split on ``\\n`` only, drop one trailing ``\\r`` per line and one BOM."""
    text = as_text(text)
    if text.startswith("﻿"):
        text = text[1:]
    return [
        line[:-1] if line.endswith("\r") else line for line in text.split("\n")
    ]


def content_lines(text):
    """Yield ``(line_number, stripped_line)`` for every non-blank,
    non-comment line. Line numbers count from 1 over *all* lines."""
    for number, raw in enumerate(split_lines(text), 1):
        line = raw.strip(BLANK)
        if not line or line.startswith("#"):
            continue
        yield number, line


def parse_date(text):
    """``datetime.date`` for a ``YYYY-MM-DD`` text that exists, else ``None``."""
    if not DATE_RE.fullmatch(text):
        return None
    try:
        return datetime.date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        return None


def parse_uint(text):
    """``int`` for ASCII digits only, else ``None``."""
    if not UINT_RE.fullmatch(text):
        return None
    try:
        return int(text)
    except ValueError:  # absurdly long digit strings
        return None
