"""``movements.txt``: what came in and went out, and the stock it adds up to."""

import re
from dataclasses import dataclass
from datetime import date as _date

from ._text import DATE_RE, SKU_RE, content_lines, parse_date, parse_uint
from .errors import ParseError

_MOVE_RE = re.compile(
    r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.DOTALL
)
_SIGNED_RE = re.compile(r"[+-]?[0-9]+")


@dataclass(frozen=True)
class Movement:
    date: _date
    sku: str
    quantity: int
    note: str = ""


def parse_movements(text, catalog):
    """Parse ``movements.txt`` text into a list of :class:`Movement` in file
    order. Raises :class:`ParseError` for a bad line, or for the line that
    first takes a product below zero (movements count in date order)."""
    moves = []
    numbers = []
    for number, line in content_lines(text):
        match = _MOVE_RE.fullmatch(line)
        if not match:
            raise ParseError(
                number, "expected DATE SKU QUANTITY [NOTE], found too few fields"
            )
        date_text, sku_text, qty_text, note = match.groups()
        when = parse_date(date_text)
        if when is None:
            raise ParseError(
                number, "bad date %r (expected a real YYYY-MM-DD)" % date_text
            )
        if not SKU_RE.fullmatch(sku_text) or sku_text.upper() not in catalog:
            raise ParseError(number, "unknown SKU %r" % sku_text)
        quantity = _parse_signed(qty_text)
        if quantity is None or quantity == 0:
            raise ParseError(
                number, "bad quantity %r (whole number, not zero)" % qty_text
            )
        moves.append(Movement(when, sku_text.upper(), quantity, note or ""))
        numbers.append(number)
    bad = first_negative(moves)
    if bad is not None:
        move = moves[bad]
        raise ParseError(
            numbers[bad],
            "stock of %s would go below zero on %s" % (move.sku, move.date),
        )
    return moves


def _parse_signed(text):
    if not _SIGNED_RE.fullmatch(text):
        return None
    if text[0] in "+-":
        value = parse_uint(text[1:])
        if value is None:
            return None
        return -value if text[0] == "-" else value
    return parse_uint(text)


def counting_order(movements):
    """Indexes of ``movements`` in the order they count: by date, same-day
    movements keeping their order in the list."""
    return sorted(range(len(movements)), key=lambda i: movements[i].date)


def first_negative(movements):
    """Index (into ``movements``) of the movement that first takes a product
    below zero in counting order, or ``None``."""
    balance = {}
    for index in counting_order(movements):
        move = movements[index]
        now = balance.get(move.sku, 0) + move.quantity
        if now < 0:
            return index
        balance[move.sku] = now
    return None


def stock_levels(catalog, movements):
    """``dict`` of SKU to the quantity on the shelf for every product in the
    catalogue (zero when it never moved), in SKU order."""
    levels = {sku: 0 for sku in sorted(catalog)}
    for move in movements:
        if move.sku in levels:
            levels[move.sku] += move.quantity
    return levels


def history(movements, sku):
    """``[(movement, balance_after), ...]`` for one SKU in counting order."""
    balance = 0
    result = []
    for index in counting_order(movements):
        move = movements[index]
        if move.sku == sku:
            balance += move.quantity
            result.append((move, balance))
    return result


def status(onhand, reorder):
    """``out`` / ``low`` / ``ok`` for a product."""
    if onhand <= 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def buy_quantity(onhand, reorder):
    """How many to buy to get back to twice the reorder level (at least 1)."""
    return max(1, 2 * reorder - onhand)
