        return -value if text[0] == "-" else value
    return parse_uint(text)


def counting_order(movements):
    """Indexes of ``movements`` in the order they count: by date, same-day
    movements keeping their order in the list."""
    return sorted(range(len(movements)), key=lambda i: movements[i].date)


