    """``dict`` of SKU to the quantity on the shelf for every product in the
    catalogue (zero when it never moved), in SKU order."""
    levels = {sku: 0 for sku in sorted(catalog)}
    for move in movements:
        if move.sku in levels:
            levels[move.sku] += move.quantity
    return levels


