    """``[(movement, balance_after), ...]`` for one SKU in counting order."""
    balance = 0
    result = []
    for index in counting_order(movements):
        move = movements[index]
        if move.sku == sku:
            balance += move.quantity
            result.append((move, balance))
    return result


