def hu(n,d): return (2*n+d)//(2*d)
def calc(nets, rates, order):
    S=sum(nets); od=hu(S*3,100)
    sh=[od*n//S for n in nets]; left=od-sum(sh)
    for i in order[:left]: sh[i]+=1
    return sum(hu((n-s)*r,100) for n,s,r in zip(nets,sh,rates)), sh, od
for p in range(25000, 40000):
