python3 - <<'EOF'
import ast,glob,re
for f in sorted(glob.glob('stockroom/*.py')+glob.glob('tests/*.py')):
    src=open(f).read(); tree=ast.parse(src)
    names=set()
    for n in ast.walk(tree):
        if isinstance(n,(ast.Import,ast.ImportFrom)):
            for a in n.names:
                names.add((a.asname or a.name).split('.')[0])
    used={n.id for n in ast.walk(tree) if isinstance(n,ast.Name)}|{n.value.id for n in ast.walk(tree) if isinstance(n,ast.Attribute) and isinstance(n.value,ast.Name)}
    un=[n for n in names if n not in used and n not in src.split('__all__')[-1]]
    if un and not f.endswith('__init__.py'): print(f,un)
EOF

